@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#e7f0ef;--muted:#8da2a4;--panel:rgba(13,25,30,.91);--line:rgba(192,225,222,.14);--cyan:#76e5d1;--gold:#e8c67a;--blue:#6bd3ed;--red:#ed777b}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0c171c;color:var(--ink);font-family:Manrope,system-ui,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}.game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#142326}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:2;top:max(12px,env(safe-area-inset-top));left:50%;transform:translateX(-50%);height:54px;width:min(760px,calc(100% - 32px));display:flex;align-items:center;padding:0 12px 0 17px;border:1px solid var(--line);border-radius:11px;background:linear-gradient(100deg,rgba(13,25,30,.96),rgba(17,34,38,.85));box-shadow:0 8px 26px #07101366;gap:14px}.brand{display:flex;align-items:center;gap:9px;min-width:145px}.brand-mark{font-size:25px;color:var(--cyan);text-shadow:0 0 14px #72eed477}.brand b{display:block;font:800 19px/17px 'Barlow Condensed',sans-serif;letter-spacing:2px}.brand small{font-size:8px;letter-spacing:1.55px;color:#8ba3a2;font-weight:800}.match-info{margin:auto;display:flex;align-items:center;gap:8px;color:#a6baba;font-size:9px;font-weight:800;letter-spacing:1px}.match-info i{height:16px;border-left:1px solid var(--line);margin:0 2px}.match-info strong{font:700 19px 'Barlow Condensed',sans-serif;color:#eff8f5;letter-spacing:1px}.live-dot,.blue-dot,.red-dot{width:7px;height:7px;display:inline-block;border-radius:50%;background:#74dfbc;box-shadow:0 0 9px #74dfbc88}.score{display:flex;align-items:center;gap:8px;font:700 17px 'Barlow Condensed',sans-serif}.score-sep{color:#738887}.blue-dot{background:var(--blue);box-shadow:0 0 8px #6bd3ed88}.red-dot{background:var(--red);box-shadow:0 0 8px #ed777b88}.icon-btn{width:32px;height:32px;border:1px solid var(--line);background:#ffffff08;color:#b9ccca;border-radius:7px;font-size:16px;cursor:pointer}.objective{position:absolute;z-index:2;top:76px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid #d5bc7138;background:#111e20c9;border-radius:5px;color:#e3d4a3;font-size:9px;font-weight:800;letter-spacing:1.2px;white-space:nowrap}.objective-icon{font-size:12px;color:var(--gold)}.objective-progress{width:56px;height:3px;background:#ffffff20;border-radius:4px;overflow:hidden}.objective-progress span{display:block;width:0;height:100%;background:var(--gold);transition:width .3s}.hero-panel{position:absolute;z-index:2;bottom:max(15px,env(safe-area-inset-bottom));left:16px;width:272px;height:76px;display:flex;align-items:center;gap:10px;padding:9px 11px;background:var(--panel);border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 22px #07101366}.hero-avatar{position:relative;display:grid;place-items:center;flex:none;width:47px;height:51px;border-radius:7px;background:linear-gradient(145deg,#429c98,#193d48 65%,#142b35);border:1px solid #8ce2d48a;box-shadow:inset 0 0 20px #5fe0b22b;color:#d9fff0;font-size:27px}.hero-avatar:after{content:'';position:absolute;inset:4px;border:1px solid #ddf6df26;border-radius:4px}.hero-avatar i{position:absolute;width:6px;height:6px;border-radius:50%;background:#fff;box-shadow:0 0 12px #fff;top:10px;right:9px}.hero-stats{flex:1;min-width:0}.hero-name{font:800 13px 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:0 0 5px}.hero-name small{float:right;color:#9bb2ad;font:700 8px Manrope,sans-serif;letter-spacing:.5px;padding-top:3px}.hero-name small b{color:#f3d37d;font-size:10px}.bar{height:10px;margin-top:3px;border-radius:2px;position:relative;overflow:hidden;background:#071215;border:1px solid #c9ffff14}.bar span{display:block;height:100%;transition:width .2s}.bar b{position:absolute;inset:0;text-align:center;color:#e9f4f0;font:700 7px/8px Manrope,sans-serif;text-shadow:0 1px 3px #000}.hp span{background:linear-gradient(90deg,#238f69,#59d6a0)}.mana span{background:linear-gradient(90deg,#2478a3,#62c5e1)}.gold-box{width:48px;display:grid;grid-template-columns:14px 1fr;align-items:center;color:var(--gold)}.gold-box span{font-size:12px}.gold-box b{font:700 15px 'Barlow Condensed',sans-serif}.gold-box small{grid-column:1/3;font-size:7px;letter-spacing:1px;color:#9eaaa0;font-weight:800;margin-top:2px}.controls{position:absolute;z-index:3;bottom:max(16px,env(safe-area-inset-bottom));right:20px;display:flex;align-items:flex-end;gap:14px}.joystick{display:none;position:relative;width:96px;height:96px;border-radius:50%;background:#17292ebf;border:1px solid #b5dad329;box-shadow:inset 0 0 0 11px #d8f4ec08,0 6px 20px #0005;touch-action:none}.joy-ring{position:absolute;inset:13px;border:1px solid #c2d7d327;border-radius:50%}.joy-knob{position:absolute;width:39px;height:39px;border-radius:50%;left:28px;top:28px;background:linear-gradient(145deg,#8fe5d4,#397f81);border:2px solid #d0fff2aa;box-shadow:0 3px 12px #06101188;pointer-events:none}.ability-row{display:flex;gap:7px;align-items:flex-end}.ability{position:relative;width:58px;height:64px;border:1px solid #c6e8df36;border-radius:9px;background:linear-gradient(155deg,#263a3fef,#101c21f5);color:#e4f0e9;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:4px 2px;box-shadow:0 5px 16px #07101377;cursor:pointer;touch-action:manipulation}.ability:active,.attack-btn:active{transform:translateY(1px);filter:brightness(1.3)}.ability .key{position:absolute;left:5px;top:3px;color:#a9bfba;font:800 9px 'Barlow Condensed',sans-serif}.spell{font-style:normal;font-size:25px;line-height:26px;color:#77dce0;text-shadow:0 0 12px currentColor}.nova-icon{color:#f3c879}.heal-icon{color:#80e2a2}.ult-icon{color:#e6a8ff}.ability b{font:800 8px 'Barlow Condensed',sans-serif;letter-spacing:.45px}.ability small{position:absolute;inset:0;display:grid;place-items:center;color:white;font:700 16px 'Barlow Condensed',sans-serif;text-shadow:0 2px 6px #000;background:#071013ad;border-radius:8px;opacity:0;pointer-events:none}.ability.cooldown small{opacity:1}.ability.locked{filter:grayscale(.7);opacity:.58}.ultimate{border-color:#cfabef6b;box-shadow:0 0 16px #bd85e61c,0 5px 16px #07101377}.attack-btn{height:58px;width:66px;border-radius:50%;border:1px solid #e8a77a8a;background:radial-gradient(circle at 35% 25%,#8d503c,#412522);color:#ffe6d4;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;box-shadow:0 0 20px #d06d3630,0 5px 18px #0006;cursor:pointer;touch-action:manipulation}.attack-btn span{font-size:23px;line-height:24px}.attack-btn b{font:800 8px 'Barlow Condensed',sans-serif;letter-spacing:.7px}.hint{position:absolute;z-index:2;bottom:102px;left:50%;transform:translateX(-50%);padding:6px 11px;border:1px solid #c5e4d91c;background:#111e20b8;border-radius:20px;color:#bdd2ca;font-size:10px;white-space:nowrap;pointer-events:none;transition:opacity .5s}.toast{position:absolute;z-index:5;top:25%;left:50%;transform:translate(-50%,-10px);padding:12px 20px;border:1px solid #e2c37c55;background:#142226ed;border-radius:7px;color:#f5dc9a;font:800 12px 'Barlow Condensed',sans-serif;letter-spacing:1px;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.modal{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#091417bb,#09141799),radial-gradient(ellipse at 50% 45%,transparent,#07111375);backdrop-filter:blur(2px);transition:opacity .35s}.modal.hidden{opacity:0;pointer-events:none}.modal-card{position:relative;width:min(460px,calc(100% - 34px));padding:33px 34px 22px;border:1px solid #b8d5cf38;border-radius:13px;background:linear-gradient(145deg,#15282bed,#0d1b20f5 72%);box-shadow:0 24px 80px #02090bd9;text-align:center;overflow:hidden}.modal-card:before{content:'';position:absolute;top:0;left:10%;width:80%;height:1px;background:linear-gradient(90deg,transparent,#b6e4d8aa,transparent)}.eyebrow{display:flex;align-items:center;justify-content:center;gap:7px;color:#9fc4b9;font-size:9px;font-weight:800;letter-spacing:1.6px}.eyebrow span{width:6px;height:6px;border-radius:50%;background:#7de3bc;box-shadow:0 0 8px #7de3bc}.modal-emblem{margin:11px auto 1px;width:48px;height:48px;display:grid;place-items:center;color:#c2f5df;font-size:30px;border:1px solid #b8e4d44d;border-radius:50%;background:radial-gradient(circle,#68c9a328,transparent 70%);text-shadow:0 0 16px #8df4cb}.modal h1{margin:5px 0 10px;font:900 42px/.9 'Barlow Condensed',sans-serif;letter-spacing:4px}.modal h1 span{display:block;margin-top:7px;color:#80d9c0;font-size:18px;letter-spacing:5px}.modal p{margin:0 auto 18px;max-width:340px;color:#aebfba;font-size:12px;line-height:1.6}.modal-facts{display:flex;justify-content:center;margin:0 auto 20px;padding:12px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.modal-facts div{flex:1;display:flex;flex-direction:column;gap:4px;border-right:1px solid var(--line)}.modal-facts div:last-child{border:0}.modal-facts b{font:700 16px 'Barlow Condensed',sans-serif;color:#e8d294}.modal-facts small{color:#8ba39d;font-size:7px;letter-spacing:.65px;font-weight:800}.primary-btn{width:100%;height:45px;border:1px solid #b8efd15e;border-radius:6px;background:linear-gradient(100deg,#448f79,#286d67);color:#effff4;font:800 12px Manrope,sans-serif;letter-spacing:1.5px;box-shadow:0 5px 20px #51c99b25;cursor:pointer}.primary-btn span{padding-left:12px;font-size:17px}.primary-btn:hover{filter:brightness(1.15)}.modal-foot{margin-top:13px;color:#839a95;font-size:9px}.modal-foot i{color:#c3d6cd;font-style:normal;padding:0 4px}.mobile-tip{display:none}
@media (pointer:fine){.joystick{display:block;opacity:.65;width:70px;height:70px}.joy-ring{inset:10px}.joy-knob{width:30px;height:30px;left:19px;top:19px}.controls{right:18px}.hint{bottom:102px}}
@media(max-width:700px){.topbar{top:max(8px,env(safe-area-inset-top));height:46px;width:calc(100% - 16px);gap:8px;padding:0 8px 0 10px}.brand{min-width:85px;gap:6px}.brand-mark{font-size:21px}.brand b{font-size:16px}.brand small{font-size:6px;letter-spacing:1px}.match-info{font-size:7px;gap:5px}.match-info strong{font-size:17px}.score{font-size:15px;gap:5px}.icon-btn{width:28px;height:28px;font-size:14px}.objective{top:60px;font-size:8px;padding:7px 9px;letter-spacing:.8px}.objective-progress{width:35px}.hero-panel{left:8px;bottom:max(10px,env(safe-area-inset-bottom));width:202px;height:64px;padding:6px;gap:7px}.hero-avatar{width:39px;height:44px;font-size:22px}.hero-name{font-size:11px;margin-bottom:3px}.hero-name small{font-size:7px}.bar{height:9px}.gold-box{width:36px}.gold-box b{font-size:13px}.gold-box small{font-size:6px}.controls{right:8px;bottom:max(11px,env(safe-area-inset-bottom));gap:7px;align-items:flex-end}.joystick{width:78px;height:78px;display:block}.joy-ring{inset:10px}.joy-knob{width:34px;height:34px;left:21px;top:21px}.ability-row{gap:4px}.ability{width:47px;height:53px;border-radius:8px}.spell{font-size:21px;line-height:22px}.ability b{font-size:7px}.attack-btn{width:51px;height:51px}.attack-btn span{font-size:20px}.attack-btn b{font-size:7px}.hint{display:none}.mobile-tip{display:none}.modal-card{padding:26px 22px 18px}.modal h1{font-size:36px}.modal p{font-size:11px}.modal-facts small{font-size:6px}}
@media(max-width:520px){.joystick{width:68px;height:68px}.joy-knob{width:30px;height:30px;left:18px;top:18px}.ability{width:41px;height:49px}.attack-btn{width:46px;height:46px}.controls{gap:5px}.ability-row{gap:3px}.hero-panel{width:174px}.hero-avatar{width:34px}.gold-box{width:29px}.match-info{margin-left:auto}.brand{min-width:74px}.score{gap:4px}.objective{top:57px}}
@media(max-height:500px){.topbar{height:40px}.objective{top:49px}.hero-panel{height:56px;bottom:7px}.controls{bottom:7px}.ability{height:49px}.joystick{width:64px;height:64px}.joy-knob{width:29px;height:29px;left:17px;top:17px}.hint{bottom:76px}.modal-card{padding:18px 25px 14px}.modal-emblem{display:none}.modal h1{font-size:33px}.modal-facts{margin-bottom:12px;padding:8px 0}}

(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const W = 1000, H = 600;
  let vw = 1000, vh = 600, dpr = 1, started = false, paused = false, ended = false, muted = true;
  let time = 0, last = 0, waveTimer = 4, enemyRespawn = 0, toastTimer = 0, shake = 0;
  const keys = {}, entities = [], particles = [], texts = [], cooldowns = {bolt:0,nova:0,heal:0,ult:0};
  const hero = {kind:'hero',team:0,x:215,y:300,r:17,hp:640,maxHp:640,mana:300,maxMana:300,speed:178,attack:58,range:155,atkCd:0,level:1,xp:0,nextXp:260,gold:250,alive:true,dir:1,target:null};
  const towers = [{kind:'tower',team:0,x:145,y:300,r:24,hp:950,maxHp:950,atkCd:0},{kind:'tower',team:1,x:835,y:300,r:24,hp:950,maxHp:950,atkCd:0}];
  const cores = [{kind:'core',team:0,x:75,y:300,r:29,hp:1550,maxHp:1550},{kind:'core',team:1,x:925,y:300,r:29,hp:1550,maxHp:1550}];
  const enemy = {kind:'enemy',team:1,x:775,y:300,r:17,hp:650,maxHp:650,speed:115,attack:37,range:145,atkCd:0,alive:true,respawn:0,level:1};
  let kills = 0, deaths = 0;
  function resize(){
    const r=canvas.getBoundingClientRect(); dpr=Math.min(devicePixelRatio||1,2); canvas.width=Math.round(r.width*dpr); canvas.height=Math.round(r.height*dpr); vw=r.width; vh=r.height;
  }
  addEventListener('resize',resize); resize();
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function say(text){const t=$('toast');t.textContent=text;t.classList.add('show');toastTimer=2.1}
  function unit(kind,team,x,y){const u={kind,team,x,y,r:kind==='creep'?9:10,hp:kind==='creep'?155:80,maxHp:kind==='creep'?155:80,speed:kind==='creep'?48:66,attack:kind==='creep'?24:17,range:kind==='creep'?82:65,atkCd:rand(0,.5),alive:true};entities.push(u);return u}
  function spawnWave(){for(let i=0;i<3;i++){unit('creep',0,192-i*18,282+i*17);unit('creep',1,808+i*18,282-i*17)};say('НОВАЯ ВОЛНА · ОТРЯДЫ ВЫШЛИ НА ЛИНИЮ')}
  function spawnFx(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-85,85),vy:rand(-85,85),life:rand(.25,.65),max:.65,color,size:rand(2,5)})}
  function floatText(x,y,text,color='#fff0b4'){texts.push({x,y,text,color,life:.8})}
  function damage(target,amount,source){if(!target.alive&&target.kind!=='tower'&&target.kind!=='core')return;target.hp-=amount;target.hit=.12;spawnFx(target.x,target.y,target.team===0?'#64ddda':'#ff8480',4);if(target.hp<=0){target.hp=0;if(target===hero){hero.alive=false;deaths++;enemyRespawn=4;say('ГЕРОЙ ПАЛ · ВОЗРОЖДЕНИЕ ЧЕРЕЗ 4 СЕК');spawnFx(hero.x,hero.y,'#69dce2',22)}else if(target===enemy){enemy.alive=false;kills++;enemyRespawn=7;gainXp(125);hero.gold+=100;say('ВРАЖЕСКИЙ ГЕРОЙ УНИЧТОЖЕН +100 ◈');spawnFx(enemy.x,enemy.y,'#ffb17a',22)}else if(target.kind==='creep'){target.alive=false;hero.gold+=22;gainXp(30)}else if(target===towers[1]){say('БАШНЯ ПАЛА · ПУТЬ К ДРЕВНЕМУ ОТКРЫТ');hero.gold+=180;shake=.45}else if(target===cores[1]){ended=true;showEnd(true)}else if(target===towers[0]){say('ВАША БАШНЯ РАЗРУШЕНА!');shake=.45}else if(target===cores[0]){ended=true;showEnd(false)}}}
  function gainXp(n){hero.xp+=n;if(hero.xp>=hero.nextXp){hero.xp-=hero.nextXp;hero.level++;hero.nextXp=Math.floor(hero.nextXp*1.35);hero.maxHp+=95;hero.hp=Math.min(hero.maxHp,hero.hp+145);hero.attack+=9;hero.maxMana+=35;hero.mana=hero.maxMana;say(`НОВЫЙ УРОВЕНЬ · ${hero.level}`);floatText(hero.x,hero.y-30,'LEVEL UP','#f5d477')}}
  function targetsFor(team){return entities.filter(e=>e.alive&&e.team!==team).concat(team===0?[enemy.alive?enemy:null,towers[1].hp>0?towers[1]:null,cores[1].hp>0?cores[1]:null].filter(Boolean):[hero.alive?hero:null,towers[0].hp>0?towers[0]:null,cores[0].hp>0?cores[0]:null].filter(Boolean))}
  function closestTarget(u,range,includeStructures=true){let all=targetsFor(u.team).filter(t=>t!==u&&dist(u,t)<=range&& (includeStructures||t.kind!=='tower'&&t.kind!=='core'));all.sort((a,b)=>{const ap=(a===hero||a===enemy)?-30:0,bp=(b===hero||b===enemy)?-30:0;return dist(u,a)+ap-dist(u,b)-bp});return all[0]||null}
  function cast(skill){if(!started||paused||ended||!hero.alive)return;let cost={bolt:45,nova:70,heal:65,ult:120}[skill],cd={bolt:4,nova:8,heal:10,ult:24}[skill];if(cooldowns[skill]>0){say('СПОСОБНОСТЬ ЕЩЁ НЕ ГОТОВА');return}if(hero.mana<cost){say('НЕДОСТАТОЧНО МАНЫ');return}hero.mana-=cost;cooldowns[skill]=cd;
    if(skill==='heal'){let a=hero.hp;hero.hp=Math.min(hero.maxHp,hero.hp+220+hero.level*25);spawnFx(hero.x,hero.y,'#89ffb2',18);floatText(hero.x,hero.y-25,'+'+Math.round(hero.hp-a),'#93ffc0');say('ВОССТАНОВЛЕНИЕ · +'+Math.round(hero.hp-a)+' HP');return}
    if(skill==='bolt'){let t=closestTarget(hero,350);if(t){damage(t,190+hero.level*28,hero);spawnFx(t.x,t.y,'#72e9fa',14);floatText(t.x,t.y-20,'РАЗРЯД','#aaf8ff')}else say('НЕТ ЦЕЛИ В РАДИУСЕ');return}
    if(skill==='nova'){let ts=targetsFor(0).filter(t=>dist(hero,t)<155);ts.forEach(t=>damage(t,125+hero.level*20,hero));spawnFx(hero.x,hero.y,'#ffd57d',28);floatText(hero.x,hero.y-34,'ВСПЫШКА','#ffe6a1');return}
    if(skill==='ult'){let t=closestTarget(hero,430);if(!t){say('НЕТ ЦЕЛИ В РАДИУСЕ');return}let x=t.x,y=t.y;setTimeout(()=>{if(!ended){spawnFx(x,y,'#e1a2ff',32);targetsFor(0).filter(u=>Math.hypot(u.x-x,u.y-y)<100).forEach(u=>damage(u,330+hero.level*42,hero));floatText(x,y-34,'МЕТЕОР','#eed1ff');shake=.18}},600)}
  }
  function attack(){if(!hero.alive)return;const t=closestTarget(hero,hero.range+30);if(t){damage(t,hero.attack,hero);hero.atkCd=.75;floatText(t.x,t.y-17,'−'+hero.attack,'#d7f4ed')}else say('ПОДОЙДИТЕ БЛИЖЕ К ЦЕЛИ')}
  function moveToward(u,t,dt){const dx=t.x-u.x,dy=t.y-u.y,d=Math.hypot(dx,dy);if(d>4){u.x+=dx/d*u.speed*dt;u.y+=dy/d*u.speed*dt;u.dir=dx>=0?1:-1}}
  function update(dt){if(!started||paused||ended)return;time+=dt;waveTimer-=dt;if(waveTimer<=0){spawnWave();waveTimer=23}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}
    Object.keys(cooldowns).forEach(k=>cooldowns[k]=Math.max(0,cooldowns[k]-dt));
    if(!hero.alive){enemyRespawn-=dt;if(enemyRespawn<=0){hero.alive=true;hero.hp=hero.maxHp;hero.mana=hero.maxMana;hero.x=215;hero.y=300;say('ВЫ ВЕРНУЛИСЬ В БОЙ');spawnFx(hero.x,hero.y,'#66e4d7',14)}}
    if(hero.alive){let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+(joy.x||0),dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+(joy.y||0),mag=Math.hypot(dx,dy);if(mag>.1){hero.x+=dx/mag*hero.speed*dt;hero.y+=dy/mag*hero.speed*dt;hero.dir=dx>0?1:-1;hero.target=null}else if(hero.target){moveToward(hero,hero.target,dt);if(Math.hypot(hero.x-hero.target.x,hero.y-hero.target.y)<8)hero.target=null}hero.x=clamp(hero.x,95,900);hero.y=clamp(hero.y,115,485);hero.atkCd-=dt;if(hero.atkCd<=0){let t=closestTarget(hero,hero.range);if(t){damage(t,hero.attack,hero);hero.atkCd=.9;spawnFx((hero.x+t.x)/2,(hero.y+t.y)/2,'#b5f5e8',3)}}}
